PAYLOAD_SHA256 = "9fe0dde9cf90e603cf3a9612a7edc9130cea9a122c43cb680cab63bf8aef6542"

def main():
    print(json.dumps(dict(event="R1_CONTROLLER_RECOVERY_BOOTSTRAP_START",
        message="程序已启动；离线安装管理修复，不安装依赖。"), ensure_ascii=False), flush=True)
    argv = sys.argv[1:]
    home = Path.home()
    if "--home" in argv:
        home = Path(argv[argv.index("--home") + 1]).expanduser().resolve()
    base = home / "paper3-r1-controller-recovery"
    base.mkdir(parents=True, exist_ok=True, mode=0o700)
    raw = base64.b85decode(PAYLOAD)
    if hashlib.sha256(raw).hexdigest() != PAYLOAD_SHA256:
        raise ValueError("RECOVERY_PAYLOAD_SHA256_DIFFERS")
    dest = base / PAYLOAD_SHA256[:20]
    with (base / "install.lock").open("a") as handle:
        fcntl.flock(handle, fcntl.LOCK_EX)
        archive = zipfile.ZipFile(io.BytesIO(raw))
        manifest = json.loads(archive.read("MANIFEST.json"))
        files = manifest["files"]
        if set(files) != {"recovery.py", "receipt_projection.py"} or set(archive.namelist()) != {*files, "MANIFEST.json"}:
            raise ValueError("RECOVERY_MEMBER_SET_DIFFERS")
        dest.mkdir(exist_ok=True, mode=0o700)
        for name, row in files.items():
            data = archive.read(name)
            if len(data) != row["bytes"] or hashlib.sha256(data).hexdigest() != row["sha256"]:
                raise ValueError("RECOVERY_MEMBER_HASH_DIFFERS")
            target = dest / name
            if target.exists():
                if target.is_symlink() or target.read_bytes() != data:
                    raise ValueError("EXISTING_IMMUTABLE_RECOVERY_DIFFERS")
            else:
                fd, temporary = tempfile.mkstemp(prefix=".install-", dir=dest)
                try:
                    with os.fdopen(fd, "wb") as out:
                        out.write(data); out.flush(); os.fsync(out.fileno())
                    os.replace(temporary, target)
                finally:
                    Path(temporary).unlink(missing_ok=True)
    print(json.dumps(dict(event="R1_CONTROLLER_RECOVERY_PACKAGE_READY", package=str(dest),
        payload_sha256=PAYLOAD_SHA256, dependency_installations=0,
        scientific_workers_signalled=0, jobs_submitted=0)), flush=True)
    sys.path.insert(0, str(dest))
    import recovery
    return recovery.main(argv)

if __name__ == "__main__":
    raise SystemExit(main())
